text:
{
  "pass": false,
  "problems": [
    {
      "type": "中身のずれ",
      "where": "summary の hs",
      "detail": "stdにある「国会への請願は議員の紹介により議長あてに提出し、委員会審査を経て本会議で採否が決まる。陳情は議員の紹介を要しない」という重要な情報が一切抜け落ちており、別の内容になっている。",
      "fix": "stdの内容に合わせて、国会への請願の手続きや陳情との違いを盛り込むように直す。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/0/text の es と hs",
      "detail": "stdは「職場などで不利に扱われることはある？」という不利益取扱に関する問いであるのに対し、esは「いやなあつかい」、hsは「子どもでも国会にお願いを出せるか」となっており、意味がずれている。",
      "fix": "stdの意味に合わせて、請願したことで職場などで不利な扱いを受けないかという内容に直す。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/1/text の hs",
      "detail": "stdにある請願法についての定め（「請願を文書で行い、受理した官公署は誠実に処理しなければならない」）が抜けている。",
      "fix": "請願法に関する記述を追加する。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/2/items/1/text の hs",
      "detail": "stdにある「同一請願者が同一会期内に同一趣旨の請願書を重ねて提出することはできない」という制限が抜けている。",
      "fix": "同じ会期中に同じ内容の請願を重ねて出せないという情報を追加する。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/2/items/2/text の hs",
      "detail": "stdにある「本会議で議決される」「内閣で措置するのが適当なものは内閣に送付される」という部分が抜け、委員会が調べるところまでしか書かれていない。",
      "fix": "本会議での議決や内閣への送付についての内容を追加する。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/5/text の hs",
      "detail": "stdにある「陳情の扱いは各議会が定めています」という情報が抜けている。",
      "fix": "陳情の扱いについての記述を追加する。"
    }
  ]
}
